 practice.updatedAt=Date.now();const index=data.items.findIndex(i=>i.id===practice!.id&&!i.deleted);if(index>=0)data.items[index]={...practice};const event={id:crypto.randomUUID(),itemId:practice.id,at:now.toISOString(),slips:slips.length,hidden:hiddenCount,grade:g,mode:wasReview?'review':'learn',step,fsrsLog};data.events.push(event);data.queue.push(event.id);if(!data.settings.days.includes(today()))data.settings.days.push(today());data.settings.lastActive=today();await save()}
 function continueResult(){result=false;if(rehearsal){practice=null;return}learned=resultLearned;if(!learned)review=practice?.learned||false;shortcut=false;position=0;slips=[];visualSlips=[]}
 async function refreshIdentity(user:any,revoked=false){const previous=account?.id;if(!user&&previous&&revoked){data=await clearStore();savedSettings=structuredClone(defaults);mergePrompt=false;mergeDismissed=false;discardPrompt=false;practice=null;result=false;learned=false;theme();message=ui.revokedNotice;}account=user;identityVerified=true;data.account=user;if(user&&!stats.statsEnabled())void api('/oauth/privacy',{enabled:false}).catch(()=>{});if(user&&previous!==user.id&&(data.items.length||data.events.length)){await afterSignin();return}await persist($state.snapshot(data));if(user){await sync();void refreshPush()}}
 async function afterSignin(){data.account=account;if(data.items.length||data.events.length){mergePrompt=true;mergeDismissed=false;(data as any).pendingMerge=true;await persist($state.snapshot(data));return}await persist($state.snapshot(data));await sync()}
 async function acceptMerge(){mergePrompt=false;(data as any).pendingMerge=false;await sync()}
 async function discardLocal(){discardPrompt=false;mergePrompt=false;(data as any).pendingMerge=false;data.items=[];data.events=[];data.queue=[];await save();await sync()}
 function editEmail(){emailSent=false;emailCode='';emailError='';emailStatus=''}
 async function sendEmail(){if(emailBusy||resendSeconds)return;emailBusy='send';emailErrorControl='send';emailError='';emailStatus='';const link=!!account;try{await api('/auth/email/start',{email:emailAddress.trim(),link});emailLink=link;emailSent=true;emailCode='';emailStatus=ui.emailSent;resendUntil=Date.now()+30000;resendSeconds=30}catch(e){emailError=e instanceof Error?e.message:String(e)}finally{emailBusy=''}}
 async function verifyEmail(){if(emailBusy||!/^\d{6}$/.test(emailCode))return;emailBusy='verify';emailErrorControl='verify';emailError='';try{const wasSignedIn=!!account;const out=await api('/auth/email/verify',{email:emailAddress.trim(),code:emailCode,link:emailLink});account=out.user||out.account;identityVerified=true;emailSent=false;emailCode='';emailOpen=false;emailStatus=wasSignedIn?ui.emailLinked:'';if(wasSignedIn){data.account=account;await persist($state.snapshot(data))}else{await afterSignin()}}catch(e){emailError=e instanceof Error?e.message:String(e)}finally{emailBusy=''}}
 function codeInput(event:Event){emailCode=(event.currentTarget as HTMLInputElement).value.replace(/\D/g,'').slice(0,6);if(emailCode.length===6)void verifyEmail()}
 function setShareCounts(event:Event){stats.setStatsEnabled((event.currentTarget as HTMLInputElement).checked);shareCounts=stats.statsEnabled();if(account)void api('/oauth/privacy',{enabled:shareCounts}).catch(()=>{})}
 async function signout(everywhere=false){await attempt(async()=>{await sync();if(data.queue.length)throw Error(ui.signoutNeedsConnection);await api(everywhere?'/auth/logout-everywhere':'/auth/logout',{});account=null;editEmail();emailStatus='';resendSeconds=0;data=await clearStore();savedSettings=structuredClone(defaults);message=ui.signedOutCleared})}
 async function exportData(){await attempt(async()=>{const out=account?await api(ui.exportPath):$state.snapshot(data);const a=document.createElement(ui.anchorTag);a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:ui.jsonMime}));a.download=ui.exportFilename;a.click();URL.revokeObjectURL(a.href);message=ui.exportReady})}
 async function deleteAccount(){await attempt(async()=>{await api(ui.accountPath,undefined,ui.deleteMethod);account=null;editEmail();emailOpen=false;resendSeconds=0;data.account=null;await persist($state.snapshot(data));confirmDelete=false;message=ui.accountDeleted})}
 async function refreshPush(){try{const health=await pushHealth(!!account);pushState=health.state;deliveries=health.results}catch{pushState='unavailable'}}
 $effect(()=>{if(ready&&tab===ui.account){account?.id;void refreshPush()}});
 $effect(()=>{const id=practice?.id,step=attemptStep,isLearned=learned,showingResult=result;if(id&&!isLearned&&!showingResult){void tick().then(()=>{window.scrollTo(0,0);practiceRegion?.focus({preventScroll:true})})}});
 async function testPush(){await attempt(async()=>{let out:any;try{out=await api(ui.testPushPath,{})}catch(e){stats.trackStats('push_test:failed');throw e}message=out.results?.length?out.results.map((r:Delivery)=>ui.pushOutcome(r.host,r.status,r.reason)).join(' '):ui.noPushDevices;await refreshPush();stats.trackStats(out.results?.some((r:Delivery)=>r.status>=200&&r.status<300)?'push_test:sent':'push_test:failed')})}
 async function enablePush(){await attempt(async()=>{if(!account)throw Error(ui.signInForReminders);if(!(ui.notificationApi in window)||!(ui.pushManagerApi in window))throw Error(ui.iosInstallNotice);const permission=await Notification.requestPermission();if(permission!==ui.permissionGranted)throw Error(ui.notificationDenied);const reg=await navigator.serviceWorker.ready;const raw=config.vapidPublicKey||config.vapid; if(!raw)throw Error(ui.vapidUnavailable);const key=Uint8Array.from(atob(raw.replace(/-/g,ui.base64Plus).replace(/_/g,ui.base64Slash)),c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api(ui.pushSubscribePath,{subscription:sub.toJSON()});data.settings.pushEnabled=true;await save();await refreshPush();stats.trackStats('reminders_enabled');message=ui.remindersEnabled})}
 async function disablePush(){await attempt(async()=>{const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();if(sub){await sub.unsubscribe();await api(ui.pushSubscribePath,{subscription:null,endpoint:sub.endpoint})}data.settings.pushEnabled=false;await save();await refreshPush()})}
 async function search(){const request=++passageRequest,generation=scriptureGeneration,tr=data.settings.defaultTranslation;found=[];await attempt(async()=>{const items=await lookupReference(reference,tr);if(request!==passageRequest||generation!==scriptureGeneration)return;if(tr==='ESV')await Promise.all(items.map(item=>ensureItemText(item as Item)));if(request!==passageRequest||generation!==scriptureGeneration)return;found=items;if(!found.length)throw Error(ui.noVersesFound);passageMode=tokenize(found.map(i=>i.text).join(' ')).length>150?'chunks':'passage'})}
 async function own(){await attempt(async()=>{if(!customTitle.trim()||!customText.trim())throw Error(ui.missingCustomText);const added=await add([{id:crypto.randomUUID(),title:customTitle.trim(),text:customText.trim(),collection:ui.personalCollection}]);if(!added)return;customTitle=ui.empty;customText=ui.empty;openCollection(addTarget||'personal')})}
 function know(){if(practice){shortcut=true;position=0;slips=[];visualSlips=[]}}
 function restart(){position=0;slips=[];visualSlips=[];result=false}
 async function remove(item:Item){item.deleted=true;item.updatedAt=Date.now();removeTarget=null;undoItem=item;await save();clearTimeout(undoTimer);undoTimer=setTimeout(()=>{if(undoItem?.id===item.id)undoItem=null},3000)}
 async function undo(){if(!undoItem)return;await attempt(async()=>{const revived={...undoItem!,deleted:false,updatedAt:Date.now()};const proposed=data.items.map(item=>item.id===revived.id?revived:item);assertEsvLimit(proposed);data.items=proposed;undoItem=null;await save()})}
 function passageItems(){if(passageMode==='separate'||found.length<2)return found;const groups=passageMode==='chunks'?Array.from({length:Math.ceil(found.length/4)},(_,i)=>found.slice(i*4,i*4+4)):[found];return groups.map(group=>({...group[0],id:group[0].id+'--'+group.at(-1).id,title:group[0].title+'–'+(group[0].title.split(':')[0]===group.at(-1).title.split(':')[0]?group.at(-1).title.split(':').at(-1):group.at(-1).title.split(' ').at(-1)),text:group.map(i=>i.text).join(' ')}))}

</script>
