 {#if emailError&&emailErrorControl===control}<p role="alert">{emailError}</p>{/if}
{/snippet}
{#snippet emailForm()}
 <form class="stack" onsubmit={(event)=>{event.preventDefault();void (emailSent?verifyEmail():sendEmail())}} aria-label={account?ui.addEmail:ui.emailSignin}>
 <label>{ui.emailAddress}<input type="email" autocomplete="email" required maxlength={254} bind:value={emailAddress} disabled={emailSent||!!emailBusy}/></label>
 {#if emailStatus}<p role="status">{emailStatus}</p>{/if}
 {#if emailSent}
 <label>{ui.emailCode}<input type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength={6} value={emailCode} oninput={codeInput} disabled={!!emailBusy}/></label>
 <Button type="submit" disabled={!!emailBusy||emailCode.length!==6}>{emailBusy==='verify'?ui.verifyingCode:ui.verifyCode}</Button>
 {@render emailFeedback('verify')}
 <Button secondary onclick={()=>void sendEmail()} disabled={!!emailBusy||resendSeconds>0}>{emailBusy==='send'?ui.sendingCode:resendSeconds?ui.resendCountdown(resendSeconds):ui.resendCode}</Button>
 {@render emailFeedback('send')}
 <Button secondary onclick={editEmail} disabled={!!emailBusy}>{ui.changeEmail}</Button>
 {:else}
 <Button type="submit" disabled={!!emailBusy||resendSeconds>0}>{emailBusy==='send'?ui.sendingCode:resendSeconds?ui.resendCountdown(resendSeconds):ui.sendCode}</Button>
 {@render emailFeedback('send')}
 {/if}
 </form>
