<svelte:window onkeydown={physical}/>
<main class:practicing={!!practice&&!learned}>
{#if !ready}<section class="empty"><h1>{ui.appName}</h1><p>{ui.loadingBody}</p></section>
{:else if oauthRoute&&identityVerified&&account}
 <section class="page mcp-consent stack" aria-labelledby="consent-title">
 <small>{ui.appName}</small><h1 id="consent-title">{ui.mcpConsentTitle}</h1>
 {#if consent}
 <p>{ui.mcpConsentIntro(consent.clientName)}</p>
 <section class="settings-group"><h2 class="mcp-client-name">{consent.clientName}</h2>{#if consent.clientDomain}<small>{consent.clientDomain}</small>{/if}<p>{ui.mcpUnverified}</p>
 <h3>{ui.mcpPermissions}</h3><ul class="mcp-scopes">{#each consent.scope as scope}<li>{ui.mcpScope(scope)}</li>{/each}</ul>
 <p>{ui.mcpRedirect(consent.redirectHost)}</p>{#if consent.redirectIsLoopback}<p class="notice">{ui.mcpLoopback}</p>{/if}</section>
 <p>{ui.mcpRevokeHint}</p>
 <form class="stack" onsubmit={(event)=>{event.preventDefault();void decideConsent('approve')}} aria-label={ui.mcpApprove}><Button type="submit" disabled={consentBusy}>{consentBusy?ui.mcpWorking:ui.mcpApprove}</Button></form>
 <form onsubmit={(event)=>{event.preventDefault();void decideConsent('deny')}} aria-label={ui.mcpDeny}><Button secondary type="submit" disabled={consentBusy}>{ui.mcpDeny}</Button></form>
 {:else if consentBusy}<p role="status">{ui.mcpLoadingConsent}</p>{/if}
 {#if consentError}<p class="notice error" role="alert">{consentError}</p>{#if !consent}<Button secondary disabled={consentBusy} onclick={()=>void loadConsent()}>{ui.mcpRetry}</Button>{/if}{/if}
 </section>
{:else if practice}
 {#if loadingPassage}<p role="status">{ui.loadingBody}</p>{/if}
 {#if learned}<section class="learned"><svg class="learned-check" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 25l9 9L39 14"/></svg><h1>{review?ui.reviewed:ui.learned}</h1><article class="keepsake" style:background={collectionColor(practice)}><p>{practice.text}</p><footer><b>{practice.title}</b>{#if practice.translation==='ESV'}<EsvAttribution translation={practice.translation}/>{:else}<small class:translation-badge={!!practice.translation}>{sourceLabel(practice)}</small>{/if}</footer></article>{#if nextDue}<small>{ui.nextReviewPrefix}{nextDue}</small>{/if}<Button onclick={loadNext}>{session.length?ui.nextItem:ui.backToToday}</Button><Button secondary onclick={()=>{learned=false;rehearsal=true;review=false;restart()}}>{ui.practiceOnceMore}</Button></section>
 {:else}<section class="practice" onpointerdown={()=>feedback.unlock(data.settings)} ontouchstart={()=>feedback.unlock(data.settings)} onpointerup={()=>feedback.unlock(data.settings)} ontouchend={()=>feedback.unlock(data.settings)} onclick={()=>feedback.unlock(data.settings)} bind:this={practiceRegion} tabindex="-1" aria-label={ui.practiceRegionLabel} inert={result} aria-hidden={result}><header><button class="icon" aria-label={ui.closePractice} onclick={()=>practice=null}>×</button><StepDots step={attemptStep}/>{#if attemptStep===1&&!review}<Button secondary onclick={know}>{ui.knowThis}</Button>{:else}<button class="icon" aria-label={ui.restartStep} onclick={restart}>↻</button>{/if}</header><div class="prompt" class:collapsed={position>0&&!titleExpanded}><small>{review?ui.reviewBlankRecall:ui.stepPrefix+attemptStep+ui.stepOfFour+[ui.empty,ui.readAlong,ui.fewWordsHidden,ui.almostFromMemory,ui.fromMemory][attemptStep]}</small><h1><button class="prompt-title" aria-expanded={titleExpanded||position===0} onclick={()=>titleExpanded=!titleExpanded}>{practice.title}</button></h1>{#if practice.translation==='ESV'}<EsvAttribution translation={practice.translation}/>{:else}<small class:translation-badge={!!practice.translation}>{sourceLabel(practice)}</small>{/if}</div><div class="progress"><i style:width={position/words.length*100+ui.percent}></i></div><VerseText {words} {mask} text={practice.text} index={position} slipped={visualSlips}/>{#key practice.id}<Keyboard hasNumbers={words.some(word=>/^\d/.test(word))} onkey={key} onpeek={()=>key(ui.empty,true)} disabled={result||completing}/>{/key}</section>{/if}
 {#if result}<Sheet title={resultTitle} close={()=>{result=false;practice=null}}><p>{resultDetail}</p><Button onclick={continueResult}>{review&&!resultLearned?ui.relearnNow:rehearsal?ui.done:resultLearned?ui.finish:ui.continue}</Button><Button secondary onclick={()=>{practice=null;result=false}}>{review&&!resultLearned?ui.later:ui.closePractice}</Button></Sheet>{/if}
{:else}
 <section class="page" class:has-toast={showAddedToast||!!undoItem} class:account={tab===ui.account}>
 <header class:collection-header={!!detail}>{#if !detail}<div><h1>{tab===ui.account?ui.accountTitle:tab===ui.gallery?ui.components:tab}</h1>{#if tab===ui.today}<p>{new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"})}</p>{/if}</div>{/if}<button class="icon" aria-label={detail?ui.backToLibrary:ui.accountSettings} onclick={()=>detail?openCollection(''):navigate(ui.account)}>{#if detail}{ui.backGlyph}{:else if data.settings.name.trim()}{data.settings.name.trim().slice(0,1).toUpperCase()}{:else}<svg class="person" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg>{/if}</button></header>
 {#if loadingPassage}<p role="status">{ui.loadingBody}</p>{/if}{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if tab===ui.today}
 <div class="rhythm"><div><b>{weekCount}{ui.of}{data.settings.goal}{ui.thisWeekSuffix}</b></div><WeekDots days={data.settings.days}/></div>
