 {:else}<div class="empty"><div class="heart">♡</div><h2>{live.length?ui.doneForToday:ui.noItemsYet}</h2>{#if !live.length}<p>{ui.addCollection}</p>{/if}<Button onclick={()=>navigate(ui.library)}>{live.length?ui.visitLibrary:ui.browseLibrary}</Button></div>{/if}
 {:else if tab===ui.library}
 {#if detail}<Cover title={collectionTitle(detail)} subtitle={plural(detailItems.length,"item")} color={starters.findIndex((s:any)=>s.id===detail)} compact/><div class="section-title"><h3>{ui.yourItems}</h3><button class="text-button" onclick={()=>{const target=detail;navigate(ui.discover);addTarget=target}}>{ui.addItems}</button></div><List>{#each detailItems as item}<Row title={item.title} subtitle={item.learned?ui.reviewDate(item.due):ui.stepPrefix+item.step} translation={item.translation} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/>{#snippet trailing()}<button class="text-button item-menu" aria-label={ui.optionsPrefix+item.title} onclick={()=>removeTarget=item}>…</button>{/snippet}</Row>{#if !item.learned&&!due.some(i=>i.id===item.id)}<button class="text-button" onclick={()=>begin([item])}>{ui.startEarly}</button>{/if}{/each}</List>{#if detailItems.length}<div class="collection-practice"><Button onclick={()=>begin(detailItems)}>{ui.startPractice}</Button></div>{:else}<p>{ui.nothingHere}</p>{/if}
 {:else}<div class="section-title"><h3>{ui.yours}</h3><button class="text-button" onclick={()=>navigate(ui.discover)}>{ui.addShortcut}</button></div><List>{#each [...new Set(live.map(i=>i.collection))] as id}{@const items=live.filter(i=>i.collection===id)}<Row title={collectionTitle(id)} subtitle={items.filter(i=>i.learned).length+ui.of+items.length+ui.learnedSuffix} onclick={()=>openCollection(id)}><ProgressPie percent={items.filter(i=>i.learned).length/items.length*100}/></Row>{/each}</List>{#if !live.length}<div class="library-empty"><p>{ui.libraryEmpty}</p><Button onclick={()=>navigate(ui.discover)}>{ui.findSomething}</Button></div>{/if}{/if}
