 <div class="discover-filters" aria-label={ui.discoverCategories}>{#each discoverFilters as filter}<button class="text-button" class:active={discoverFilter===filter} aria-pressed={discoverFilter===filter} onclick={()=>filterDiscover(filter)}>{filter}</button>{/each}</div>
 <label class="translation-picker">{ui.defaultTranslation}<select bind:value={data.settings.defaultTranslation} onchange={changeTranslation}>{#each passageTranslations as value}<option>{value}</option>{/each}</select></label><div class="segments" aria-label={ui.contentType}>{#each [[ui.verseMode,ui.verses],[ui.ownMode,ui.yourText],[ui.documentsMode,ui.catechisms]] as [id,label]}<button class="segment" class:active={addMode===id} aria-pressed={addMode===id} onclick={()=>{passageRequest++;loadingPassage=false;addMode=id;discoverFilter=id===ui.documentsMode?'Catechisms & creeds':'All';found=[]}}>{label}</button>{/each}</div>
 {#if addMode===ui.verseMode&&discoverFilter==='All'}<label>{ui.bibleReference}<input bind:value={reference} placeholder={ui.referencePlaceholder} onkeydown={e=>{if(e.key===ui.enterKey)void search()}}/></label><Button onclick={()=>void search()} disabled={busy}>{ui.findVerses}</Button>{#if found.length}<div class="passage-actions">{#if data.settings.defaultTranslation!==incord.esv}<div class="segments passage-segments" aria-label={ui.passageMode}>{#each [['passage',ui.onePassage],['separate',ui.separateVerses],['chunks',ui.chunks]] as [mode,label]}<button class="segment" class:active={passageMode===mode} aria-pressed={passageMode===mode} onclick={()=>passageMode=mode}>{label}</button>{/each}</div>{/if}<Button onclick={()=>void add(passageItems(),undefined,false,tokenize(found.map(i=>i.text).join(' ')).length>500)}>{ui.addToLibrary}</Button></div><List>{#each found as item}<Row title={item.title} subtitle={item.text} translation={item.translation} onclick={item.translation===incord.esv?()=>void previewFound(item):undefined}/>{/each}</List>{/if}{#if data.settings.defaultTranslation!==incord.esv}<small>{ui.publicDomainNotice}</small>{/if}
 {:else if addMode===ui.ownMode}<label>{ui.titleOrQuestion}<input bind:value={customTitle} maxlength={200}/></label><label>{ui.textToRemember}<textarea bind:value={customText} maxlength={10000}></textarea></label><p>{ui.privateTextNotice}</p><Button onclick={()=>void own()}>{ui.addYourText}</Button>
 {/if}
 {#if addMode!==ui.ownMode}
 {#if discoverFilter==='All'||discoverFilter==='Topics'}<section aria-labelledby="topics-heading"><h2 id="topics-heading" class="section-title">{ui.topics}</h2><div class="topic-cards passage-cards">{#each topics as topic,i}<Cover title={topic.title} subtitle={`${topic.verseCount} verses · ${topic.description}`} translation={data.settings.defaultTranslation} color={i} onclick={()=>void previewTopic(topic.id)}/>{/each}</div></section>{/if}
 {#if discoverFilter==='All'||discoverFilter==='Passages'}<section aria-labelledby="passages-heading"><h3 id="passages-heading" class="section-title">{ui.passages}</h3><p>{ui.passageDetail}</p><div class="passage-cards">{#each passages as passage,i}<div class="scripture-card"><Cover title={passage.reference} subtitle={`${passage.verseCount} verses · ${passage.title}`} color={i} translation={data.settings.defaultTranslation} onclick={()=>{if(!busy)void previewPassage(passage.id)}}/></div>{/each}</div></section>{/if}
 {#if discoverFilter==='All'||discoverFilter==='Catechisms & creeds'}<section aria-labelledby="documents-heading"><h2 id="documents-heading" class="section-title">{ui.catechismsAndCreeds}</h2><div class="document-cards passage-cards">{#each documents as doc,i}<Cover title={doc.title} subtitle={documentSubtitle(doc)} color={i} onclick={()=>{selectedDoc=doc.id;void tick().then(()=>document.getElementById('document-browser')?.scrollIntoView({block:'start'}))}}/>{/each}</div><label id="document-browser">{ui.browse}<select bind:value={selectedDoc}><option value="">{ui.chooseDocument}</option>{#each documents as doc}<option value={doc.id}>{doc.title}{doc.questionCount?` · ${ui.questionCount(doc.questionCount)}`:ui.empty}</option>{/each}</select></label>{#if selectedDoc}{@const doc=documents.find((d:any)=>d.id===selectedDoc)}{#if doc}<header class="document-intro"><h2>{doc.title}</h2><p>{doc.subtitle}</p>{#if doc.description}<p>{doc.description}</p>{/if}</header><div class="bulk-actions">{#if doc.items.length>12}<Button secondary onclick={()=>void add(doc.items.slice(0,12),doc.id)}>{['apostles','nicene'].includes(doc.id)?ui.addFirstArticles:ui.addFirstQuestions}</Button><Button secondary onclick={()=>void add(doc.items.filter(i=>!live.some(x=>x.id===i.id)).slice(0,12),doc.id)}>{['apostles','nicene'].includes(doc.id)?ui.addNextArticles:ui.addNextQuestions}</Button>{/if}<Button secondary onclick={()=>{confirmBatch=doc.items;batchCollection=doc.id}}>{ui.addAll}</Button></div><List>{#each doc.items as item,i}{#if item.lordsDay&&(i===0||doc.items[i-1].lordsDay!==item.lordsDay)}<h3>{ui.lordsDay(item.lordsDay)}</h3>{/if}<div class="document-row"><details><summary>{['apostles','nicene'].includes(doc.id)?ui.articleTitle(item.number||i+1,item.text):(item.number?ui.questionPrefix(item.number):'')+item.title}</summary><p>{item.text}</p></details><button class="icon document-add" aria-label={live.some(x=>x.id===item.id)?ui.added:!['apostles','nicene'].includes(doc.id)&&item.number?ui.addQuestion(item.number):ui.addArticle} disabled={live.some(x=>x.id===item.id)} onclick={()=>void add([item],doc.id)}>{live.some(x=>x.id===item.id)?'✓':'+'}</button></div>{/each}</List>{/if}{/if}</section>{/if}{/if}</div>
 {:else if tab===ui.account}
 <div class="stack">{#if oauthRoute}<section class="notice stack"><h2>{ui.mcpSigninTitle}</h2><p>{ui.mcpSigninDetail}</p>{#if consentError}<p role="alert">{consentError}</p>{/if}</section>{/if}<section class="settings-group" aria-labelledby="account-heading"><h3 id="account-heading">{ui.yourAccount}</h3>{#if account}<p>{ui.signedIn}</p>{#if mergePrompt&&mergeDismissed}<Button secondary onclick={()=>mergeDismissed=false}>{ui.reviewDeviceItems}</Button>{/if}{#if config.email&&!account.hasEmail}{#if !emailOpen}<Button secondary onclick={()=>{emailOpen=true;editEmail()}}>{ui.addEmail}</Button>{:else}{@render emailForm()}{/if}{/if}{#if emailStatus&&!emailOpen}<p role="status">{emailStatus}</p>{/if}{#if !online}<small>{ui.offlineSync}</small>{/if}<Button secondary onclick={()=>confirmSignout=true}>{ui.signOut}</Button><Button secondary onclick={()=>confirmEverywhere=true}>{ui.signoutEverywhere}</Button>{:else}<p>{ui.localAccountNotice}</p>{#if config.googleEnabled??config.google}<Button disabled={!!emailBusy} onclick={googleSignin}>{ui.continueGoogle}</Button>{/if}{#if config.email}{@render emailForm()}{/if}{/if}</section><section class="settings-group" aria-labelledby="connected-apps-heading"><h3 id="connected-apps-heading">{ui.mcpConnectedApps}</h3><p>{ui.mcpConnectedDetail}</p><a href="/connect">{ui.mcpConnectGuide}</a>{#if account}{#if appsLoading}<p role="status">{ui.mcpLoadingApps}</p>{:else if !connectedApps.length&&!appsError}<p>{ui.mcpNoApps}</p>{/if}{#each connectedApps as app (app.id)}<article class="mcp-app stack"><h3>{app.clientName}</h3><small>{ui.mcpConnectedDate(app.connectedAt)}</small><small>{app.lastUsed===null?ui.mcpNeverUsed:ui.mcpLastUsed(app.lastUsed)}</small><ul class="mcp-scopes">{#each app.scope as scope}<li>{ui.mcpScope(scope)}</li>{/each}</ul><Button secondary disabled={!!revoking} onclick={()=>void revokeApp(app)}>{revoking===app.id?ui.mcpRevoking:ui.mcpRevoke}</Button></article>{/each}{#if appsError}<p role="alert">{appsError}</p><Button secondary disabled={appsLoading||!!revoking} onclick={()=>void loadConnectedApps()}>{ui.mcpRetry}</Button>{/if}{#if appsStatus}<p role="status">{appsStatus}</p>{/if}{/if}</section><section class="settings-group" aria-label={ui.preferences}><label>{ui.displayName}<input bind:value={data.settings.name} onchange={()=>void save()} maxlength={80}/></label><label>{ui.appearance}<select bind:value={data.settings.theme} onchange={(event)=>{data.settings.theme=event.currentTarget.value;stats.trackStats(`theme:${data.settings.theme}`);void save()}}><option value="system">{ui.system}</option><option value="light">{ui.light}</option><option value="dark">{ui.dark}</option></select></label><label>{ui.textSize}<select bind:value={data.settings.textSize} onchange={(event)=>{data.settings.textSize=event.currentTarget.value;stats.trackStats(`text_size:${data.settings.textSize}`);void save()}}>{#each ui.textSizes as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>{ui.defaultTranslation}<select bind:value={data.settings.defaultTranslation} onchange={changeTranslation}>{#each passageTranslations as value}<option>{value}</option>{/each}</select></label><label>{ui.weeklyRhythm}<select bind:value={data.settings.goal} onchange={()=>void save()}>{#each RULES.rhythmOptions as n}<option value={n}>{ui.weekOption(n)}</option>{/each}</select></label><div class="feedback-setting"><div class="feedback-controls"><label class="toggle"><input type="checkbox" bind:checked={data.settings.keySounds} onchange={(event)=>{data.settings.keySounds=event.currentTarget.checked;void save()}}/>{ui.keySounds}</label><button class="text-button" onclick={()=>feedback.testSound()}>{ui.testSound}</button></div><small>{ui.soundHelp}</small></div>{#if hapticsSupported}<div class="feedback-setting"><div class="feedback-controls"><label class="toggle"><input type="checkbox" bind:checked={data.settings.haptics} onchange={(event)=>{data.settings.haptics=event.currentTarget.checked;void save()}}/>{ui.haptics}</label><button class="text-button" onclick={()=>feedback.testHaptic()}>{ui.testHaptic}</button></div><small>{ui.hapticHelp}</small></div>{/if}<label>{ui.reminderTime}<input type="time" bind:value={data.settings.reminderTime} onchange={()=>void save()}/></label><label>{ui.newPerDay}<select bind:value={(data.settings as any).newPerDay} onchange={()=>void save()}>{#each [1,2,3,5] as n}<option value={n}>{n}</option>{/each}</select></label><label>{ui.searchZones}<input type="search" placeholder={ui.searchZones} bind:value={zoneSearch}/></label><label>{ui.timeZone}<select bind:value={data.settings.timeZone} onchange={()=>void save()}>{#each zones.filter(z=>z===data.settings.timeZone||z.toLowerCase().includes(zoneSearch.toLowerCase())) as zone}<option>{zone}</option>{/each}</select></label>
 </section><section class="settings-group" aria-labelledby="reminder-heading"><h3 id="reminder-heading">{ui.reminders}</h3><p>{ui.reminderInstructions}</p><p>{pushState==='on'?ui.reminderOn:pushState==='missing'?ui.reminderMissing:pushState==='denied'?ui.reminderDenied:pushState==='unsupported'?ui.iosInstallNotice:pushState==='unavailable'?ui.deliveryUnavailable:ui.reminderOff}</p><Button secondary disabled={pushState==='denied'||pushState==='unsupported'} onclick={()=>void (pushState==='on'?disablePush():enablePush())}>{pushState==='on'?ui.disableReminders:pushState==='missing'?ui.turnOnAgain:ui.enableReminders}</Button>{#if pushState==='on'}<Button secondary onclick={()=>void testPush()}>{ui.sendTestPush}</Button>{/if}<details><summary>{ui.deliveryLog}</summary>{#if deliveries.length}<ul>{#each deliveries as delivery}<li><small>{delivery.time?new Date(delivery.time).toLocaleString():''} · {ui.pushProvider(delivery.host)}</small><p>{ui.pushOutcome(delivery.host,delivery.status,delivery.reason)}</p></li>{/each}</ul>{:else}<p>{ui.deliveryEmpty}</p>{/if}</details>
 </section><section class="settings-group" aria-labelledby="privacy-heading"><h3 id="privacy-heading">{incord.privacy}</h3><label><input type="checkbox" bind:checked={shareCounts} disabled={privacySignal} onchange={setShareCounts}/>{incord.shareCounts}</label><small>{incord.countsDetail}</small>{#if privacySignal}<small>{incord.privacySignal}</small>{/if}</section><section class="settings-group" aria-label={ui.dataLabel}><Button secondary onclick={()=>void exportData()}>{ui.exportData}</Button>{#if account}<Button secondary onclick={()=>confirmDelete=true}>{ui.deleteAccount}</Button>{/if}</section><section class="settings-group" aria-labelledby="send-feedback-heading"><h3 id="send-feedback-heading">{ui.feedbackTitle}</h3><p>{ui.feedbackDetail}</p><form class="stack feedback-form" aria-label={ui.feedbackTitle} novalidate onsubmit={event=>{event.preventDefault();void sendFeedback()}} autocomplete="off">
 <label>{ui.feedbackKind}<select bind:value={feedbackKind} disabled={feedbackBusy} aria-label={ui.feedbackKind}>{#each ui.feedbackKinds as kind}<option>{kind}</option>{/each}</select></label>
 <label>{ui.feedbackMessage}<textarea bind:value={feedbackMessage} minlength={10} maxlength={4000} required disabled={feedbackBusy} aria-describedby="feedback-message-help"></textarea></label><small id="feedback-message-help">{ui.feedbackMessageHelp}</small>
 <label>{ui.feedbackContact}<input name="feedback-reply" type="email" bind:value={feedbackContact} maxlength={254} disabled={feedbackBusy} autocomplete="off" aria-describedby="feedback-contact-help"/></label><small id="feedback-contact-help">{ui.feedbackContactHelp}</small>
 <label class="toggle"><input type="checkbox" bind:checked={feedbackIncludeMeta} disabled={feedbackBusy} aria-describedby="feedback-meta-help"/>{ui.feedbackIncludeMeta}</label><small id="feedback-meta-help">{ui.feedbackMetaHelp}</small>
 <button type="submit" disabled={feedbackBusy} aria-busy={feedbackBusy} class:feedback-sending={feedbackBusy}>{feedbackBusy?ui.feedbackSending:ui.feedbackSend}</button>
 {#if feedbackError||feedbackStatus}<p class="feedback-result" class:feedback-failed={!!feedbackError} bind:this={feedbackResult} role={feedbackError?'alert':'status'} tabindex="-1">{feedbackError||feedbackStatus}</p>{/if}
 </form></section><section class="settings-group" aria-label={ui.aboutLabel}><h3>{ui.aboutVersion(appVersion)}</h3><small>{ui.aboutApp}</small><EsvAttribution translation={incord.esv} full/><p>{incord.privacyAbout}</p><a href="/privacy">{incord.privacyPolicy}</a>{#if supportUrl(config.donateUrl)}<a href={supportUrl(config.donateUrl)!} rel="noopener noreferrer">{ui.supportIncord}</a>{/if}</section></div>
 {:else if tab===ui.gallery}<div class="gallery"><Button>{ui.primaryButton}</Button><Button secondary>{ui.secondaryButton}</Button><StepDots step={3}/><WeekDots days={data.settings.days}/><Cover title={ui.gospelTitle} subtitle={ui.galleryVerseCount} color={0} large/><Row title={ui.johnReference} subtitle={ui.galleryStep} translation={ui.bsb}><StepDots step={2}/></Row><VerseText words={[ui.sampleFor,ui.sampleGod,ui.sampleSo,ui.sampleLoved,ui.sampleThe,ui.sampleWorld]} mask={[false,true,false,true,true,false]} index={2}/><Keyboard onkey={()=>{}} onpeek={()=>{}}/></div>{/if}
 </section><TabBar active={tab} onchange={navigate}/>
{/if}
{#if confirmDelete}<Sheet title={ui.deleteTitle} close={()=>confirmDelete=false}><p>{ui.deleteInstructions}</p><Button onclick={()=>void deleteAccount()}>{ui.confirmDelete}</Button><Button secondary onclick={()=>confirmDelete=false}>{ui.keepAccount}</Button></Sheet>{/if}
{#if welcome}<Sheet title={ui.welcomeBack} close={()=>welcome=false}><p>{ui.welcomeCount(Math.min(3,live.filter(i=>i.learned).length))}</p><Button onclick={()=>{data.settings.returnStart=today();welcome=false;void save()}}>{ui.start}</Button><Button secondary onclick={()=>{data.settings.returnStart=today();welcome=false;void save();begin(live.filter(i=>i.learned).slice(0,3))}}>{ui.checkMemory}</Button></Sheet>{/if}
{#if preview}<Sheet title={preview.title} close={()=>preview=null}><List>{#each preview.items as item}<Row title={item.title} subtitle={item.text} translation={item.translation}/>{/each}</List><Button onclick={()=>void addStarter(preview)}>{ui.addToMyLibrary}</Button></Sheet>{/if}
{#if removeTarget}<Sheet title={ui.removeTitle} close={()=>removeTarget=null}><p>{ui.removeDetail(removeTarget.title)}</p><Button onclick={()=>void remove(removeTarget!)}>{ui.remove}</Button><Button secondary onclick={()=>removeTarget=null}>{ui.keepItem}</Button></Sheet>{/if}
{#if showAddedToast}<div class="added-toast" role="status">{addedToast}</div>{/if}
{#if undoItem&&!practice}<div class="undo-toast" role="status">{ui.removed} <button class="text-button" onclick={()=>void undo()}>{ui.undo}</button></div>{/if}
{#if confirmBatch}<Sheet title={ui.batchTitle(confirmBatch.length)} close={()=>confirmBatch=null}><Button onclick={()=>{const items=confirmBatch!;confirmBatch=null;void add(items,batchCollection,true)}}>{ui.addItems}</Button><Button secondary onclick={()=>confirmBatch=null}>{ui.cancel}</Button></Sheet>{/if}
{#if confirmSignout}<Sheet title={ui.signoutTitle} close={()=>confirmSignout=false}><p>{ui.signoutDetail}</p><Button onclick={()=>{confirmSignout=false;void signout()}}>{ui.signOut}</Button><Button secondary onclick={()=>confirmSignout=false}>{ui.cancel}</Button></Sheet>{/if}
{#if !oauthRoute&&mergePrompt&&!mergeDismissed&&!discardPrompt}<Sheet title={ui.mergeTitle(live.length)} close={()=>mergeDismissed=true}><p>{ui.mergeHistoryDetail}</p><Button onclick={()=>void acceptMerge()}>{ui.mergeAdd}</Button><Button secondary onclick={()=>discardPrompt=true}>{ui.keepSeparate}</Button></Sheet>{/if}
{#if discardPrompt}<Sheet title={ui.discardTitle} close={()=>discardPrompt=false}><p>{ui.discardDetail}</p><Button onclick={()=>void discardLocal()}>{ui.discardLocal}</Button><Button secondary onclick={()=>discardPrompt=false}>{ui.cancel}</Button></Sheet>{/if}
{#if confirmEverywhere}<Sheet title={ui.signoutEverywhereTitle} close={()=>confirmEverywhere=false}><p>{ui.signoutEverywhereDetail}</p><Button onclick={()=>{confirmEverywhere=false;void signout(true)}}>{ui.signoutEverywhere}</Button><Button secondary onclick={()=>confirmEverywhere=false}>{ui.cancel}</Button></Sheet>{/if}

</main>
